// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Stored triangle selector.
*/
type Triangle = 'upper' | 'lower';

/**
* Interface describing reciprocal Cholesky pivot growth.
*/
interface Routine {
	/**
	* Computes reciprocal pivot growth from a supplied matrix and factor.
	*
	* @param order - storage layout
	* @param uplo - stored triangle
	* @param NCOLS - leading square prefix order
	* @param A - original matrix
	* @param LDA - leading dimension of A
	* @param AF - supplied Cholesky factor
	* @param LDAF - leading dimension of AF
	* @param WORK - scratch storage with 2*NCOLS indexed entries
	* @returns reciprocal pivot growth
	*/
	( order: Layout, uplo: Triangle, NCOLS: number, A: Float64Array, LDA: number, AF: Float64Array, LDAF: number, WORK: Float64Array ): number;

	/**
	* Computes reciprocal pivot growth using independent view indexing.
	*
	* @param uplo - stored triangle
	* @param NCOLS - leading square prefix order
	* @param A - original matrix
	* @param strideA1 - row stride of A
	* @param strideA2 - column stride of A
	* @param offsetA - starting index of A
	* @param AF - supplied factor
	* @param strideAF1 - row stride of AF
	* @param strideAF2 - column stride of AF
	* @param offsetAF - starting index of AF
	* @param WORK - scratch storage, disjoint from inputs
	* @param strideWork - nonzero scratch stride
	* @param offsetWork - starting scratch index
	* @returns reciprocal pivot growth
	*/
	readonly ndarray: ( uplo: Triangle, NCOLS: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, AF: Float64Array, strideAF1: number, strideAF2: number, offsetAF: number, WORK: Float64Array, strideWork: number, offsetWork: number ) => number;
}

/**
* Computes the reciprocal Cholesky pivot-growth factor.
*/
declare var dlaPorpvgrw: Routine;


// EXPORTS //

export = dlaPorpvgrw;
